import { HomeMain } from '../../slots/defs/homeMain';
import { PeopleColumns, PersonCells } from '../../slots/defs/peopleColumns';
import { useCurrentSheet, useCurrentUser } from '../session/session';
import { usePeople, type Person } from '../people/people';
import { counts, sumOf, useClaims, type Claim } from '../claims/claims';
import { dueOf, rateOf, sumDue, useRates, type Rate } from './rates';

// A person's due-total: the dues fixed on their settled claims, plus the rest of their claimed times
// their grade's rate, divided by 100, rounded half up (n/a when the grade has no rate and there is a
// live part to price); and the sheet's due-total, everyone's added up, skipping n/a.
function personDue(person: Person, claims: Claim[], rates: Rate[] | undefined): string {
  const mine = claims.filter((c) => c.personId === person.id && counts(c));
  const fixed = mine.filter((c) => c.due !== null);
  const live = mine.filter((c) => c.due === null);
  const liveDue = dueOf(sumOf(live), rateOf(rates, person.grade));
  if (fixed.length === 0) return liveDue;
  if (live.length > 0 && liveDue === 'n/a') return 'n/a';
  return sumDue([...fixed.map((c) => c.due as string), ...(live.length > 0 ? [liveDue] : [])]);
}

function DueHeader() {
  return <th>Due</th>;
}

